package com.p2p.escrow.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.context.annotation.*; import org.springframework.http.HttpHeaders; import org.springframework.http.HttpMethod; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.AuthorityUtils; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter; import org.springframework.web.cors.*; import java.io.IOException;
@Configuration public class SecurityConfig { @Bean SecurityFilterChain security(HttpSecurity h,JwtService jwt, CorsConfigurationSource cors)throws Exception{return h.csrf(c->c.disable()).cors(c->c.configurationSource(cors)).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.OPTIONS,"/**").permitAll().requestMatchers("/api/auth/**","/ws/**").permitAll().anyRequest().authenticated()).addFilterBefore(new JwtFilter(jwt),UsernamePasswordAuthenticationFilter.class).build();} @Bean CorsConfigurationSource cors(){CorsConfiguration c=new CorsConfiguration();c.addAllowedOriginPattern("http://localhost:*");c.addAllowedOriginPattern("http://127.0.0.1:*");c.addAllowedHeader("*");c.addAllowedMethod("*");var s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;} static class JwtFilter extends OncePerRequestFilter {final JwtService jwt;JwtFilter(JwtService j){jwt=j;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain f)throws ServletException,IOException{String h=r.getHeader(HttpHeaders.AUTHORIZATION);if(h!=null&&h.startsWith("Bearer "))try{var a=new UsernamePasswordAuthenticationToken(jwt.parse(h.substring(7)),null,AuthorityUtils.NO_AUTHORITIES);org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(a);}catch(Exception ignored){}f.doFilter(r,p);} } }
